			return &tasks[i], nil
		}
	}

	// Fall back to partial match.
	for i := range tasks {
		if strings.Contains(strings.ToLower(normalizeWhitespace(tasks[i].Content)), norm) {
			return &tasks[i], nil
		}
	}

	return nil, nil
}

