	})
	defer srv.Close()

	_, err := c.GetTasks("", "priority 1 & #Work")
	if err != nil {
		t.Fatal(err)
	}
}

func TestGetTasks_withBothProjectIDAndFilter(t *testing.T) {
	c, srv := testServer(t, func(w http.ResponseWriter, r *http.Request) {
